import type { AgentTeamClaim, AgentTeamMemberId, AgentTeamProjectRef, AgentTeamTask, AgentTeamTaskRef } from './types/entities.ts'

export const REVIEW_BACKLOG_IDLE_MS = 30 * 60 * 1000
export const STALLED_PUBLIC_MS = 24 * 60 * 60 * 1000
export const STALLED_IDLE_MS = 24 * 60 * 60 * 1000

export type ReminderKind = 'review-backlog' | 'stalled'

export interface ReminderClaimFacts {
  readonly claim: AgentTeamClaim
  readonly createdSequence: number
}

export interface ReminderTaskFacts {
  readonly task: AgentTeamTask
  readonly projectActive: boolean
  readonly statusBaselineSequence: number
  readonly statusBaselineOccurredAt: string
  readonly latestPublicSequence: number
  readonly latestPublicOccurredAt: string
  readonly claims: readonly ReminderClaimFacts[]
}

export interface ReminderEvaluationInput {
  readonly nowMs: number
  readonly tasks: readonly ReminderTaskFacts[]
  readonly isOwner: (projectRef: AgentTeamProjectRef, memberId: AgentTeamMemberId) => boolean
  readonly isAvailable: (memberId: AgentTeamMemberId) => boolean
  /** Milliseconds idle, or undefined when this Host has not observed a complete running → idle interval. */
  readonly idleMs: (memberId: AgentTeamMemberId) => number | undefined
  readonly heldEver: (taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId) => boolean
  readonly episodeExists: (taskRef: AgentTeamTaskRef, kind: ReminderKind, recipient: AgentTeamMemberId, baselineSequence: number) => boolean
  readonly hasUnreadResponsibility: (taskRef: AgentTeamTaskRef, recipient: AgentTeamMemberId) => boolean
}

export interface ReminderCandidate {
  readonly taskRef: AgentTeamTaskRef
  readonly kind: ReminderKind
  readonly recipient: AgentTeamMemberId
  readonly baselineSequence: number
}

export function reviewReminderRecipient(task: AgentTeamTask,
  isOwner: (projectRef: AgentTeamProjectRef, memberId: AgentTeamMemberId) => boolean,
  heldEver: (taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId) => boolean): AgentTeamMemberId {
  return task.accountable === 'member:human'
    || !isOwner(task.projectRef, task.accountable)
    || heldEver(task.taskRef, task.accountable)
    ? 'member:human' as AgentTeamMemberId : task.accountable
}

function eligible(input: ReminderEvaluationInput, candidate: ReminderCandidate): boolean {
  return !input.episodeExists(candidate.taskRef, candidate.kind, candidate.recipient, candidate.baselineSequence)
    && !input.hasUnreadResponsibility(candidate.taskRef, candidate.recipient)
}

/** Evaluate every open Task once. Unknown runtime presence never becomes an idle duration. */
export function planTaskReminders(input: ReminderEvaluationInput): readonly ReminderCandidate[] {
  const candidates: ReminderCandidate[] = []
  for (const facts of input.tasks) {
    const { task } = facts
    if (!facts.projectActive || task.resolution !== 'open') continue
    if (task.status === 'in_review') {
      const recipient = reviewReminderRecipient(task, input.isOwner, input.heldEver)
      const idleMs = input.idleMs(recipient)
      const ready = recipient === 'member:human'
        ? input.nowMs - Date.parse(facts.statusBaselineOccurredAt) >= REVIEW_BACKLOG_IDLE_MS
        : idleMs !== undefined && idleMs >= REVIEW_BACKLOG_IDLE_MS
      const candidate = { taskRef: task.taskRef, kind: 'review-backlog' as const, recipient, baselineSequence: facts.statusBaselineSequence }
      if (ready && input.isAvailable(recipient) && eligible(input, candidate)) candidates.push(candidate)
      continue
    }
    if (task.status !== 'in_progress') continue
    const activeClaims = facts.claims.filter(entry => entry.claim.state === 'active')
    const quiet = input.nowMs - Date.parse(facts.latestPublicOccurredAt) > STALLED_PUBLIC_MS
    const executorIdle = activeClaims.some(entry => {
      const idleMs = input.idleMs(entry.claim.owner)
      return idleMs !== undefined && idleMs > STALLED_IDLE_MS
    })
    const baselineSequence = Math.max(facts.latestPublicSequence, ...activeClaims.map(entry => entry.createdSequence))
    const candidate = { taskRef: task.taskRef, kind: 'stalled' as const, recipient: task.accountable, baselineSequence }
    if ((quiet || executorIdle) && input.isAvailable(task.accountable) && eligible(input, candidate)) candidates.push(candidate)
  }
  return candidates
}

/**
 * Registry of every model-facing recovery line the Team renders: one entry per situation, built from the values the rejection holds so the line names the refused value. It lives in the Host because both tools and the ledger reject, and tools import the Host, never the reverse. `assertRecoveryCoverage` refuses entries no situation reaches; `forbidHandWrittenRecovery` scans model-facing sources for route sentences outside the registry.
 */

/** What a rejection hands the registry: the values the sentence should name. */
export interface RecoveryContext {
  /** The value the model passed that was refused, echoed so the line is concrete. */
  readonly refused?: string | undefined
  /** The Thread the rejected action was aimed at, when there is one. */
  readonly threadRef?: string | undefined
  /** The Task the rejected action was aimed at, when there is one. */
  readonly taskRef?: string | undefined
  /** The Project the rejected action was aimed at, when there is one. */
  readonly projectRef?: string | undefined
  /** The tool action whose parameter shape was wrong, when the fault is a shape. */
  readonly action?: string | undefined
  /** The parameter that belongs to another action, when the fault is that one. */
  readonly parameter?: string | undefined
  /** The action that parameter does belong to, when the fault is that one. */
  readonly owner?: string | undefined
}

/** One registered way out: the situation it answers, and its words. */
export interface RecoveryEntry {
  /** The rejection kind this entry answers, exactly as the rejecting code spells it. */
  readonly kind: string
  /** The sentence, built from the context so it can name real values. */
  readonly sentence: (context: RecoveryContext) => string
}

/** One entry per model-facing fault, naming the next action and its value. Lookup is by exact kind so a new kind cannot inherit a neighbour's sentence. */
export const RECOVERY_REGISTRY: readonly RecoveryEntry[] = Object.freeze([
  {
    kind: 'unread_required',
    sentence: ({ threadRef, taskRef }: RecoveryContext) => [
      'Read the pending updates with team_thread read before reconsidering this write.',
      ...(threadRef === undefined ? [] : [threadRef]),
      ...(taskRef === undefined ? [] : [taskRef]),
    ].join(' '),
  },
  {
    kind: 'main_unread_required',
    sentence: ({ projectRef }: RecoveryContext) => `Read the pending Main stream updates with team_thread read and projectRef${projectRef === undefined ? '' : ` ${projectRef}`} before reconsidering this post.`,
  },
  {
    kind: 'project_owner_required',
    sentence: ({ projectRef }: RecoveryContext) => `Only a Project owner starts or promotes a Thread — use team_message post to speak in ${projectRef === undefined ? 'the Project' : projectRef}'s Main stream, and mention an owner when the work needs one.`,
  },
  {
    kind: 'accountable_owner_required',
    sentence: ({ taskRef }: RecoveryContext) => `Only the Task's accountable owner or the Human does this${taskRef === undefined ? '' : ` (${taskRef})`} — ask them in the Thread, or, when you are the accountable, use team_task transfer first.`,
  },
  {
    kind: 'self_acceptance_forbidden',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent who held any Claim on${taskRef === undefined ? ' this Task' : ` ${taskRef}`} cannot accept it — if you are the accountable owner, use team_task transfer to give an uninvolved owner responsibility for acceptance; otherwise ask the accountable owner or the Human in the Thread to arrange verification.`,
  },
  {
    kind: 'accountable_target_invalid',
    sentence: ({ taskRef }: RecoveryContext) => `The accountable must be an enabled Project owner here or the Human${taskRef === undefined ? '' : ` (${taskRef})`} — choose a current owner with team_view as the accountable and retry; only the Human may transfer a finished Task.`,
  },
  {
    kind: 'accept_requires_in_review',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent accepts only an in_review Task${taskRef === undefined ? '' : ` (${taskRef})`} — mark your Claim done with team_task done to hand it to review, or ask the Human to accept early.`,
  },
  {
    kind: 'not_project_member',
    sentence: ({ projectRef }: RecoveryContext) => `Only Project members take part in ${projectRef === undefined ? 'a Project' : projectRef} — choose a Project listed by team_view, or ask the Human or a Project owner to mention you there.`,
  },
  {
    kind: 'main_stream_addressing',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'threadRef and projectRef'} address different things — pass threadRef to read a Thread, or projectRef to read a Project's Main stream, and retry with one of them.`,
  },
  {
    kind: 'unread_remaining',
    sentence: () => 'call team_thread read again.',
  },
  {
    kind: 'stale_revision',
    sentence: () => 'Read the Thread, reconsider the new facts, then retry with the token that read returns.',
  },
  {
    // Same refusal as `stale_revision` with a different cause: the token was never a revision this Thread reached. The race sentence would send the model hunting for a nonexistent insertion. A distinct kind keeps exact-kind lookup reachable.
    kind: 'stale_revision_token_unrecognized',
    sentence: ({ threadRef }: RecoveryContext) => [
      'That write token is not a revision this Thread reached — nobody inserted anything, so there is nothing to go and re-read.',
      `Take a current token from ${threadRef === undefined ? 'the Thread' : threadRef} with team_thread read, or reuse the one your own last committed mutation rendered.`,
    ].join(' '),
  },
  {
    kind: 'missing_thread_identity',
    sentence: () => 'Copy a threadRef (or a taskRef on a Taskful Thread) from team_inbox or team_view, then retry.',
  },
  {
    kind: 'missing_message_ref',
    sentence: ({ refused }: RecoveryContext) => `Copy the messageRef you were shown${refused === undefined ? '' : ` (${refused})`}, then retry.`,
  },
  {
    kind: 'history_only_arguments',
    sentence: ({ action }: RecoveryContext) => `${action ?? 'read'} drains unread and cannot page — drop beforeSequence and limit, or call action: history to page older facts.`,
  },
  {
    kind: 'action_only_arguments',
    // Named by parameter: `messageRef` belongs to `message` alone and would otherwise be dropped silently.
    sentence: ({ action, parameter, owner }: RecoveryContext) => `${action ?? 'read'} does not accept ${parameter ?? 'that parameter'} — drop it, or call action: ${owner ?? 'message'} where it belongs.`,
  },
  {
    kind: 'missing_write_token',
    sentence: () => 'Drain the Thread with team_thread read and copy the next-write token it renders, or reuse the one your own last committed mutation rendered.',
  },
  {
    kind: 'start_requires_project',
    sentence: () => 'start opens a new Thread: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'post_requires_project',
    sentence: () => 'post speaks in a Project\'s Main stream: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'dm_requires_member',
    sentence: () => 'Copy the memberRef of an enabled Agent from team_view; a DM is a private note, so shared work belongs in a Thread reply.',
  },
  {
    kind: 'claim_requires_direction',
    sentence: () => 'claim opens a new Claim with your one-sentence direction — drop claimRef, or use done/release to change an existing one.',
  },
  {
    kind: 'claim_close_requires_ref',
    sentence: ({ action }: RecoveryContext) => `Copy the claimRef of your own Claim from team_task list or the Thread read; you can only ${action ?? 'close'} a Claim you own.`,
  },
  {
    kind: 'promote_requires_thread',
    sentence: () => 'promote needs the threadRef of the discussion Thread to turn into a Task — copy it from team_thread read or the Main stream card.',
  },
  {
    kind: 'task_action_requires_task',
    sentence: ({ action }: RecoveryContext) => `${action ?? 'This action'} needs a taskRef — copy one from team_task board or the Task's Thread read.`,
  },
  {
    kind: 'list_takes_task_only',
    sentence: () => 'Drop baseRevision, direction, claimRef, and threadRef — list takes only taskRef.',
  },
  {
    kind: 'board_takes_no_task',
    sentence: () => 'board reads the whole board — drop taskRef, threadRef, baseRevision, direction, and claimRef; to reach one Task, copy its taskRef from the board and use list.',
  },
  {
    kind: 'promote_takes_thread',
    sentence: () => 'promote works on a discussion Thread — drop taskRef, direction, and claimRef, and pass threadRef with the Thread’s current write token.',
  },
  {
    kind: 'claim_owned_by_another',
    sentence: ({ refused }: RecoveryContext) => `Claim ${refused ?? ''} belongs to another Member or another Task — list this Task's Claims with team_task list and close one of your own.`,
  },
  {
    kind: 'reply_target_unknown',
    sentence: ({ refused }: RecoveryContext) => `Reply target ${refused ?? ''} is not a recorded Message — copy a messageRef rendered by team_thread read, team_view, or an inbox notice.`,
  },
  {
    kind: 'attachment_path_rejected',
    sentence: ({ refused }: RecoveryContext) => `Attachment ${refused ?? ''} was refused — attachments are absolute paths to one existing non-empty file within the byte limit; fix the path or drop the attachment.`,
  },
  {
    kind: 'unknown_ref',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'That ref'} does not name anything this workspace holds — reuse the full ref exactly as returned by Team tools, or list the candidates with team_view.`,
  },
  {
    kind: 'ambiguous_ref',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'That ref'} matches several entries — reuse a longer prefix, or the full ref exactly as returned by Team tools.`,
  },
  {
    kind: 'workspace_required',
    sentence: ({ refused }: RecoveryContext) => `workspace is required when you participate in multiple Workspaces — choose one of: ${refused ?? ''}.`,
  },
  {
    kind: 'workspace_ambiguous',
    // `refused` already reads "workspace:X matches '…001', '…002'", so this
    // sentence supplies the verdict and the route and never a second verb.
    sentence: ({ refused }: RecoveryContext) => `${refused ?? ''} — that prefix is ambiguous: reuse a longer prefix, or the full Workspace id exactly as listed.`,
  },
  {
    kind: 'workspace_not_participating',
    sentence: ({ refused }: RecoveryContext) => `Not participating in Workspace ${refused ?? ''} — copy a full id from team_view, or a unique prefix of at least 6 hex characters.`,
  },
])

/** Every kind the registry answers, for the coverage check below. */
export const RECOVERY_KINDS: readonly string[] = Object.freeze(RECOVERY_REGISTRY.map(entry => entry.kind))

/** Look one entry up by exact kind; an unregistered kind is a bug, never a silent fallback. */
export function recoveryFor(kind: string): RecoveryEntry {
  const entry = RECOVERY_REGISTRY.find(candidate => candidate.kind === kind)
  if (entry === undefined) throw new Error(`no registered recovery for '${kind}'; add an entry to RECOVERY_REGISTRY`)
  return entry
}

/** Refuses a registry entry no produced situation reaches, and a produced situation with no entry. */
export function assertRecoveryCoverage(producedKinds: readonly string[]): void {
  const produced = new Set(producedKinds)
  for (const entry of RECOVERY_REGISTRY) {
    if (!produced.has(entry.kind)) {
      throw new Error(`recovery entry '${entry.kind}' matches no situation the Team produces`)
    }
  }
  for (const kind of produced) {
    if (!RECOVERY_KINDS.includes(kind)) throw new Error(`situation '${kind}' has no registered recovery`)
  }
}

/** Refuses a hand-written recovery sentence in model-facing source. Comments are stripped before the scan, so only what a model would read is checked. */
export function forbidHandWrittenRecovery(source: string, fileName: string): void {
  if (fileName.endsWith('recovery-hints.ts')) return
  const withoutComments = stripComments(source)
  // Imperative route shapes only: a bare `retry` also names variables and policies.
  const routePatterns = [
    /\b(then )?retry (this|it|the|with|again|without|after|a)\b/i,
    /\bcopy (a|an|the) [a-zA-Z]+ (from|rendered by|you were shown)/i,
    /\buse (action|reply|done|release)\b/i,
    /\bcall (team_|action:)/i,
    /\bdrop (them|it|beforeSequence|baseRevision|claimRef|direction)\b/i,
  ]
  for (const pattern of routePatterns) {
    const match = pattern.exec(withoutComments)
    if (match !== null) {
      const line = withoutComments.slice(0, match.index).split('\n').length
      throw new Error(`${fileName}:${line} spells a recovery route by hand; register it in recovery-hints.ts instead`)
    }
  }
}

/** Drop comments and their contents, preserving line numbering so a hit points at real code. */
function stripComments(source: string): string {
  return source.replaceAll(/\/\*[\s\S]*?\*\//gu, match => match.replaceAll(/[^\n]/gu, ' '))
    .replaceAll(/(^|[^:])\/\/[^\n]*/gu, (match, lead: string) => `${lead}${' '.repeat(match.length - lead.length)}`)
}

    lastOperationId: head?.operationId ?? null,
  })
}

/** Current human display name for @ matching and uniqueness checks. */
humanDisplayHandle(): string {
  return this.humanHandle
}

/** Read-only inputs for one event-evaluated reminder pass. */
reminderFacts(): readonly import('./task-reminders.ts').ReminderTaskFacts[] {
  return Object.freeze([...this.state.tasks.values()].filter(task => task.resolution === 'open').map(task => {
    const latest = this.state.factsByThread.get(task.threadRef)?.at(-1)
    const statusBaseline = this.state.taskStatusBaselines.get(task.taskRef)
    if (latest === undefined || statusBaseline === undefined) throw new Error('invalid Task reminder baseline')
    return Object.freeze({ task, projectActive: this.state.projects.get(task.projectRef)?.state === 'active',
      statusBaselineSequence: statusBaseline.sequence,
      statusBaselineOccurredAt: this.state.occurredAtBySequence.get(statusBaseline.sequence) ?? '',
      latestPublicSequence: latest.sequence,
      latestPublicOccurredAt: latest.occurredAt,
      claims: Object.freeze((this.state.claimsByTask.get(task.taskRef) ?? []).map(claim => Object.freeze({ claim,
        createdSequence: this.state.claimCreatedSequenceByRef.get(claim.claimRef) ?? latest.sequence }))),
    })
  }))
}

heldTaskClaim(taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId): boolean {
  return this.heldTaskClaimFrom(this.state, taskRef, memberId)
}

reminderEpisodeExists(taskRef: AgentTeamTaskRef, kind: import('./task-reminders.ts').ReminderKind,
  recipient: AgentTeamMemberId, baselineSequence: number): boolean {
  return this.state.reminderEpisodes.has(reminderEpisodeKey(taskRef, kind, recipient, baselineSequence))
}

hasUnreadResponsibility(taskRef: AgentTeamTaskRef, recipient: AgentTeamMemberId): boolean {
  const threadRef = this.state.tasks.get(taskRef)?.threadRef
  return threadRef !== undefined && this.activityMarkersForFrom(this.state, recipient, threadRef).length > 0
}

planReminders(nowMs: number, idleMs: (memberId: AgentTeamMemberId) => number | undefined,
  taskRef?: AgentTeamTaskRef): readonly import('./task-reminders.ts').ReminderCandidate[] {
  return planTaskReminders({ nowMs, tasks: this.reminderFacts().filter(facts => taskRef === undefined || facts.task.taskRef === taskRef),
    isOwner: (projectRef, memberId) => memberId === AGENT_TEAM_HUMAN_MEMBER_ID || this.projectOwnerIds(projectRef).includes(memberId),
    isAvailable: memberId => memberId === AGENT_TEAM_HUMAN_MEMBER_ID || this.getMember(memberId)?.state === 'enabled',
    idleMs, heldEver: (taskRef, memberId) => this.heldTaskClaim(taskRef, memberId),
    episodeExists: (taskRef, kind, recipient, baselineSequence) => this.reminderEpisodeExists(taskRef, kind, recipient, baselineSequence),
    hasUnreadResponsibility: (taskRef, recipient) => this.hasUnreadResponsibility(taskRef, recipient) })
}

/** Recheck the whole condition after earlier writes in the queue; a stale baseline or recipient is not committable. */
raiseReminder(candidate: import('./task-reminders.ts').ReminderCandidate, nowMs: number,
  idleMs: (memberId: AgentTeamMemberId) => number | undefined): Promise<AgentTeamOperationReceipt | undefined> {
  return this.enqueue(async () => {
    const { taskRef, kind, recipient, baselineSequence } = candidate
    const candidateKey = reminderEpisodeKey(taskRef, kind, recipient, baselineSequence)
    if (!this.planReminders(nowMs, idleMs, taskRef).some(current => reminderEpisodeKey(current.taskRef, current.kind, current.recipient, current.baselineSequence) === candidateKey)) return undefined
    const task = this.state.tasks.get(taskRef)
    const project = task === undefined ? undefined : this.state.projects.get(task.projectRef)
    if (task === undefined || project === undefined || project.state !== 'active'
      || (kind === 'review-backlog' ? task.status !== 'in_review' : task.status !== 'in_progress')) return undefined
    const sequence = this.nextSequence()
    const marker: AgentTeamReminderMarker = Object.freeze({ memberId: recipient, threadRef: task.threadRef, taskRef, kind, baselineSequence, sequence })
    const requestId = `agent-team:reminder:${taskRef}:${kind}:${recipient}:${baselineSequence}` as AgentTeamRequestId
    const operation: AgentTeamReminderRaisedOperation = Object.freeze({
      ...this.operationBase({ requestId, actor: HOST_ACTOR }, sequence), kind: 'team/reminder-raised',
      data: Object.freeze({ workspaceId: project.workspaceId, taskRef, kind, recipient, baselineSequence,
        inbox: this.inboxDelta([], [], [], [], [], [], [], [], [marker]) }),
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return this.receipt(operation)
  })
}

/**
 * Sync the runtime human display name from Host settings. Never persisted:
 * a rename affects only later @ resolutions and handle checks.
 */
setHumanDisplayHandle(handle: string): void {
  const name = handle.normalize('NFKC').trim()
  if (name !== '') this.humanHandle = name
}

initialize(request: AgentTeamInitializeRequest = {
  requestId: AGENT_TEAM_INITIALIZE_REQUEST_ID,
  actor: HUMAN_ACTOR,
  humanMemberId: AGENT_TEAM_HUMAN_MEMBER_ID,
}): Promise<AgentTeamLedgerResult<AgentTeamOperationReceipt>> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameInitialization(existing, request)
      await this.adoptRulesVersion()
      return this.resolved(this.receipt(existing))
    }
    if (this.state.ordered.length !== 0) throw new Error('agent-team ledger has operations but no initialization request')
    const operation: AgentTeamInitializedOperation = Object.freeze({
      sequence: 1,
      operationId: this.createOperationId(),
      requestId: request.requestId,
      occurredAt: this.createOccurredAt(),
      actor: Object.freeze({ ...request.actor }),
      previousOperationId: null,
      kind: 'team/initialized',
      data: Object.freeze({ humanMemberId: request.humanMemberId }),
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    await this.adoptRulesVersion()
    return this.committed(this.receipt(operation))
  })
}

/**
 * Append the marker for a rules version this build implements but the ledger has not adopted.
 * It runs inside initialize's queued task, so it precedes every later write — startup recovery's included.
 */
private async adoptRulesVersion(): Promise<void> {
  if (this.state.rulesVersion >= this.rulesVersion) return

    : activity.kind === 'reopen'
      ? this.reopenThreadInboxFrom(projection, activity, thread.threadRef)
      : this.withReminderCleanup(this.acceptThreadInboxFrom(projection, activity, thread.threadRef,
        activity.acceptedClaimRefs !== undefined ? activity.acceptedClaimRefs : expectedCompletedClaimRefs), projection, thread.threadRef)
  if (!isDeepStrictEqual(operation.data.inbox, expectedInbox)) throw new Error('invalid Task inbox projection')
  this.validateInboxDelta(operation.data.inbox, projection, refs, [], [], [activity])
  return
}
if (operation.kind === 'team/reminder-raised') {
  if (operation.actor.kind !== 'host') throw new Error('invalid Task reminder authority')
  const { taskRef, kind, recipient, baselineSequence, inbox } = operation.data
  const task = projection.tasks.get(taskRef)
  const thread = task === undefined ? undefined : projection.threads.get(task.threadRef)
  const project = task === undefined ? undefined : projection.projects.get(task.projectRef)
  const marker = inbox.reminderMarkers?.added[0]
  const key = reminderEpisodeKey(taskRef, kind, recipient, baselineSequence)
  if (task === undefined || thread === undefined || project === undefined || project.workspaceId !== operation.data.workspaceId
    || (kind === 'review-backlog' ? task.status !== 'in_review' : task.status !== 'in_progress')
    || projection.reminderEpisodes.has(key) || baselineSequence >= operation.sequence
    || !projection.occurredAtBySequence.has(baselineSequence)
    || (kind === 'review-backlog'
      ? projection.taskStatusBaselines.get(taskRef)?.sequence !== baselineSequence
      : baselineSequence !== Math.max(projection.factsByThread.get(task.threadRef)?.at(-1)?.sequence ?? 0,
        ...(projection.claimsByTask.get(taskRef) ?? []).filter(claim => claim.state === 'active')
          .map(claim => projection.claimCreatedSequenceByRef.get(claim.claimRef) ?? 0)))
    || (recipient !== humanMemberId && (projection.members.get(recipient)?.state === undefined || !this.participatesInFrom(projection, recipient, project.workspaceId)))
    || marker === undefined || inbox.reminderMarkers?.added.length !== 1 || inbox.reminderMarkers.removed.length !== 0
    || !isDeepStrictEqual(marker, { memberId: recipient, threadRef: task.threadRef, taskRef, kind, baselineSequence, sequence: operation.sequence })
    || !isDeepStrictEqual(inbox, this.inboxDelta([], [], [], [], [], [], [], [], [marker]))) {
    throw new Error('invalid Task reminder projection')
  }
  this.validateInboxDelta(inbox, projection, refs)
  return
}
if (operation.kind === 'team/dm-sent') {
  const sender = assertMember()
  const recipient = projection.members.get(operation.data.recipientMemberId)
  if (recipient === undefined || !this.participatesInFrom(projection, recipient.memberId, operation.data.workspaceId)
    || recipient.state !== 'enabled' || recipient.memberId === AGENT_TEAM_HUMAN_MEMBER_ID
    || operation.data.senderMemberId !== sender.memberId

      return []
    case 'team/thread-promoted':
      return [{ kind: 'project', projectRef: operation.data.task.projectRef }, { kind: 'thread', threadRef: operation.data.thread.threadRef }]
    case 'team/claim-created':
    case 'team/claim-done':
    case 'team/claim-released':
    case 'team/task-changed':
